use molten_core::fabric::ReferenceSystemKind;
use molten_core::fabric_simulation::{apply_reference_operation, initial_reference_state, DistributedSchedulerOperation, ReferenceJobPhase, ReferenceServiceOperation, ReferenceServiceState};

fn main() {
    let mut state = initial_reference_state(ReferenceSystemKind::DistributedScheduler);
    for operation in [
        DistributedSchedulerOperation::Submit { job_id: "job-a".into() },
        DistributedSchedulerOperation::Lease { job_id: "job-a".into(), owner: "worker-a".into() },
        DistributedSchedulerOperation::Failover { job_id: "job-a".into(), next_owner: "worker-b".into() },
        DistributedSchedulerOperation::Failover { job_id: "job-a".into(), next_owner: "worker-a".into() },
    ] {
        state = apply_reference_operation(&state, &ReferenceServiceOperation::DistributedScheduler(operation)).unwrap().next;
    }
    let result = apply_reference_operation(&state, &ReferenceServiceOperation::DistributedScheduler(
        DistributedSchedulerOperation::Complete { job_id: "job-a".into(), owner: "worker-a".into(), completion_ref: format!("blake3:{}", "a".repeat(64)) }
    )).unwrap();
    let ReferenceServiceState::DistributedScheduler(scheduler) = &result.next else { panic!("wrong reference service") };
    let job = scheduler.jobs.get("job-a").unwrap();
    assert_eq!(job.lease_epoch, 3);
    assert_eq!(job.phase, ReferenceJobPhase::Completed);
    assert_eq!(job.lease_owner.as_deref(), Some("worker-a"));
    assert!(job.authoritative_completion_ref.is_some());
    assert!(result.semantic_invariants.contains(&"completion-requires-current-lease"));
    println!("owner-returns baseline: A@1 -> B@2 -> A@3; token-free Complete by A accepted; phase=completed; current_epoch=3; service_claims_current_lease=true");
}
